package com.bank.factory;

import java.math.BigDecimal;

// Implements Cloneable so we can demonstrate clone()-based creation.
class Account implements Cloneable {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    // Public arg constructor — used by new AND by reflection (Constructor.newInstance).
    public Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }

    // No-arg constructor — what the deprecated Class.newInstance would require.
    public Account() {
        this("UNKNOWN", "UNKNOWN", BigDecimal.ZERO);
    }

    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void setBalance(BigDecimal b) { this.balance = b; }

    // clone() copies fields WITHOUT calling a constructor.
    @Override public Account clone() {
        try {
            return (Account) super.clone(); // shallow copy; BigDecimal is immutable so safe here
        } catch (CloneNotSupportedException e) {
            throw new AssertionError("Account is Cloneable", e);
        }
    }

    @Override public String toString() {
        return "Account{" + accountId + ", " + holderName + ", " + balance + "}";
    }
}
