package com.bank.factory;

import java.math.BigDecimal;

// Static factory method: named, validating, can return cached/subtypes.
class AccountFactory {

    // Validates before constructing — a key benefit over raw 'new'.
    static Account openSavings(String accountId, String holderName, BigDecimal opening) {
        if (opening.signum() < 0) {
            throw new IllegalArgumentException("Opening balance cannot be negative");
        }
        return new Account(accountId, holderName, opening); // ultimately calls new
    }
}
