package com.bank.factory;

import java.lang.reflect.Constructor;
import java.lang.reflect.InvocationTargetException;
import java.math.BigDecimal;
import java.util.logging.*;

public class ObjectCreationDemo {
    private static final Logger log = Logger.getLogger(ObjectCreationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        // 1) new — the everyday path, runs the constructor.
        Account viaNew = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        log.info(() -> "via new      : " + viaNew);

        // 2) Factory method — validates, then calls new internally.
        Account viaFactory = AccountFactory.openSavings("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        log.info(() -> "via factory  : " + viaFactory);

        // 3) Reflection — modern Constructor.newInstance, CAN pass arguments.
        Class<?> clazz = Account.class;
        Constructor<?> ctor = clazz.getDeclaredConstructor(String.class, String.class, BigDecimal.class);
        Account viaReflection = (Account) ctor.newInstance("SAV9001", "Reflected User", new BigDecimal("500"));
        log.info(() -> "via reflect  : " + viaReflection);

        // 4) clone — copies fields WITHOUT a constructor.
        Account snapshot = viaNew.clone();
        snapshot.setBalance(new BigDecimal("999999"));
        log.info(() -> "via clone    : " + snapshot + " (original unchanged: " + viaNew + ")");

        // 5) The DEPRECATED Class.newInstance vs the CORRECT replacement.
        try {
            @SuppressWarnings("deprecation")
            Account viaOld = (Account) Account.class.newInstance(); // deprecated: no-arg only, leaks checked exc
            log.warning(() -> "via Class.newInstance (DEPRECATED): " + viaOld
                    + " — only no-arg, hides checked exceptions");
        } catch (InstantiationException | IllegalAccessException e) {
            log.log(Level.SEVERE, "Class.newInstance failed", e);
        }

        Account viaCorrect = (Account) Account.class.getDeclaredConstructor().newInstance();
        log.info(() -> "via getDeclaredConstructor().newInstance() (CORRECT): " + viaCorrect);
    }
}

